private:
    void _init() {
        GraphContextObj const& contextObj = abi_context();
        NodeObj const& nodeObj = abi_node();
        {
            auto inputDataHandles0 = getAttributesR<
                ConstAttributeDataHandle, ConstAttributeDataHandle, ConstAttributeDataHandle, ConstAttributeDataHandle,
                ConstAttributeDataHandle, ConstAttributeDataHandle, ConstAttributeDataHandle
                >(contextObj, nodeObj.nodeContextHandle, std::make_tuple(
                    inputs::exec.m_token, inputs::gpu.m_token, inputs::instanceMappingInfoSDPtr.m_token, inputs::renderProductResolution.m_token,
                    inputs::rp.m_token, inputs::semanticFilterName.m_token, inputs::semanticLabelTokenSDCudaPtr.m_token
                )
            , kAccordingToContextIndex);
            auto outputDataHandles0 = getAttributesW<
                AttributeDataHandle, AttributeDataHandle
                >(contextObj, nodeObj.nodeContextHandle, std::make_tuple(
                    outputs::exec.m_token, outputs::semanticFilterSegmentationMapCudaPtr.m_token
                )
            , kAccordingToContextIndex);
            inputs.exec.setContext(contextObj);
            inputs.exec.setHandle(std::get<0>(inputDataHandles0));
            inputs.gpu.setContext(contextObj);
            inputs.gpu.setHandle(std::get<1>(inputDataHandles0));
            inputs.instanceMappingInfoSDPtr.setContext(contextObj);
            inputs.instanceMappingInfoSDPtr.setHandle(std::get<2>(inputDataHandles0));
            inputs.renderProductResolution.setContext(contextObj);
            inputs.renderProductResolution.setHandle(std::get<3>(inputDataHandles0));
            inputs.rp.setContext(contextObj);
            inputs.rp.setHandle(std::get<4>(inputDataHandles0));
            inputs.semanticFilterName.setContext(contextObj);
            inputs.semanticFilterName.setHandle(std::get<5>(inputDataHandles0));
            inputs.semanticLabelTokenSDCudaPtr.setContext(contextObj);
            inputs.semanticLabelTokenSDCudaPtr.setHandle(std::get<6>(inputDataHandles0));
            outputs.exec.setContext(contextObj);
            outputs.exec.setHandle(std::get<0>(outputDataHandles0));
            outputs.semanticFilterSegmentationMapCudaPtr.setContext(contextObj);
            outputs.semanticFilterSegmentationMapCudaPtr.setHandle(std::get<1>(outputDataHandles0));
        }
        tryGetDynamicAttributes<AttributePortType::kAttributePortType_Input>(staticAttributeCount, m_dynamicInputs);
        tryGetDynamicAttributes<AttributePortType::kAttributePortType_Output>(staticAttributeCount, m_dynamicOutputs);
        tryGetDynamicAttributes<AttributePortType::kAttributePortType_State>(staticAttributeCount, m_dynamicStates);

        collectMappedAttributes(m_mappedAttributes);

        m_canCachePointers = contextObj.iContext->canCacheAttributePointers ?
                                 contextObj.iContext->canCacheAttributePointers(contextObj) : true;
    }

public:
    static void initializeType(const NodeTypeObj& nodeTypeObj)
    {
        const INodeType* iNodeType = nodeTypeObj.iNodeType;
        OgnSdPostSemanticFilterSegmentationMapDatabase::tokens.InstanceMapSD = NameToken("InstanceMapSD");
        OgnSdPostSemanticFilterSegmentationMapDatabase::tokens.InstanceSegmentationSD = NameToken("InstanceSegmentationSD");

        inputs::exec.initialize(*iNodeType, nodeTypeObj);
        inputs::gpu.initialize(*iNodeType, nodeTypeObj);
        inputs::instanceMappingInfoSDPtr.initialize(*iNodeType, nodeTypeObj);
        inputs::renderProductResolution.initialize(*iNodeType, nodeTypeObj);
        inputs::rp.initialize(*iNodeType, nodeTypeObj);
        inputs::semanticFilterName.initialize(*iNodeType, nodeTypeObj);
        inputs::semanticLabelTokenSDCudaPtr.initialize(*iNodeType, nodeTypeObj);

        outputs::exec.initialize(*iNodeType, nodeTypeObj);
        outputs::semanticFilterSegmentationMapCudaPtr.initialize(*iNodeType, nodeTypeObj);

        iNodeType->setMetadata(nodeTypeObj, kOgnMetadataExtension, "omni.syntheticdata");
        iNodeType->setMetadata(nodeTypeObj, kOgnMetadataTokens, "[\"InstanceMapSD\", \"InstanceSegmentationSD\"]");
        iNodeType->setMetadata(nodeTypeObj, kOgnMetadataCategories, "graph:postRender");
        iNodeType->setMetadata(nodeTypeObj, kOgnMetadataDescription, "Synthetic Data node to create an texture AOV : the semantic segmentation map corresponding to an input semantic filter");
    }
    static void initialize(const GraphContextObj&, const NodeObj& nodeObj)
    {
        const INode* iNode = nodeObj.iNode;
        AttributeObj attr;
        attr = iNode->getAttributeByToken(nodeObj, inputs::exec.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "Trigger");
        attr = iNode->getAttributeByToken(nodeObj, inputs::gpu.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "Pointer to shared context containing gpu foundations");
        attr = iNode->getAttributeByToken(nodeObj, inputs::instanceMappingInfoSDPtr.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "uint buffer pointer containing the following information : [numInstances, minInstanceId, numSemantics, minSemanticId, numProtoSemantic]");
        attr = iNode->getAttributeByToken(nodeObj, inputs::renderProductResolution.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "RenderProduct resolution");
        attr = iNode->getAttributeByToken(nodeObj, inputs::rp.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "Render results");
        attr = iNode->getAttributeByToken(nodeObj, inputs::semanticFilterName.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "Name of the semantic filter");
        attr = iNode->getAttributeByToken(nodeObj, inputs::semanticLabelTokenSDCudaPtr.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "uint64_t cuda buffer pointer of size numSemantics containing the semantic label token");
        attr = iNode->getAttributeByToken(nodeObj, outputs::exec.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "Executes for each newFrame event received");
        attr.iAttribute->setMetadata(attr, kOgnMetadataUiName, "Received");
        attr = iNode->getAttributeByToken(nodeObj, outputs::semanticFilterSegmentationMapCudaPtr.token());
        attr.iAttribute->setMetadata(attr, kOgnMetadataDescription, "uint64_t cuda array containing the segmentation map associated to the input semantic filter");
    }
